import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"守志","description":"","frontmatter":{"title":"守志","date":"2026-11-24T00:00:00.000Z","seq":65,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王逸","source_book":"楚辞","prev":{"text":"哀岁","link":"/blogs/楚辞/哀岁.html"},"next":{"text":"卷首 · 全 65 篇目录","link":"/blogs/楚辞/index.html"}},"headers":[],"relativePath":"blogs/楚辞/守志.md","filePath":"blogs/楚辞/守志.md"}'),o={name:"blogs/楚辞/守志.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="守志" tabindex="-1">守志 <a class="header-anchor" href="#守志" aria-label="Permalink to &quot;守志&quot;">​</a></h1><p class="poem-meta">先秦 · 王逸　·　九思</p><div class="poem"><p class="poem-stanza">陟玉峦兮逍遥，览高冈兮峣峣。</p><p class="poem-stanza">桂树列兮纷敷，吐紫华兮布条。</p><p class="poem-stanza">实孔鸾兮所居，今其集兮惟鸮。</p><p class="poem-stanza">乌鹊惊兮哑哑，余顾盼兮怊怊。</p><p class="poem-stanza">彼日月兮闇昧，障覆天兮祲氛。</p><p class="poem-stanza">伊我后兮不聪，焉陈诚兮效忠。</p><p class="poem-stanza">摅羽翮兮超俗，游陶遨兮养神。</p><p class="poem-stanza">乘六蛟兮蜿蝉，遂驰骋兮升云。</p><p class="poem-stanza">扬彗光兮为旗，秉电策兮为鞭。</p><p class="poem-stanza">朝晨发兮鄢郢，食时至兮增泉。</p><p class="poem-stanza">绕曲阿兮北次，造我车兮南端。</p><p class="poem-stanza">谒玄黄兮纳贽，崇忠贞兮弥坚。</p><p class="poem-stanza">历九宫兮遍观，睹秘藏兮宝珍。</p><p class="poem-stanza">就传说兮骑龙，与织女兮合婚。</p><p class="poem-stanza">举天罼兮掩邪，彀天弧兮射奸。</p><p class="poem-stanza">随真人兮翱翔，食元气兮长存。</p><p class="poem-stanza">望太微兮穆穆，睨三阶兮炳分。</p><p class="poem-stanza">相辅政兮成化，建烈业兮垂勋。</p><p class="poem-stanza">目瞥瞥兮西没，道遐回兮阻叹。</p><p class="poem-stanza">志稸积兮未通，怅敞罔兮自怜。</p><p class="poem-stanza">乱曰：</p><p class="poem-stanza">天庭明兮云霓藏，三光朗兮镜万方。</p><p class="poem-stanza">斥蜥蜴兮进龟龙，策谋从兮翼机衡。</p><p class="poem-stanza">配稷契兮恢唐功，嗟英俊兮未为双。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
